import clusterdata.datatypes.TaskEvent;

public class TaskEventParser {
    public static TaskEvent parseTaskEvent(String line) {
        String[] fields = line.split(",", -1);  // -1 to keep trailing empty fields

        if (fields.length < 6) {
            return null;  // Invalid line
        }

        TaskEvent event = new TaskEvent();

        try {
            event.timestamp = Long.parseLong(fields[0]);
            event.missingInfo = fields[1];
            event.jobId = Long.parseLong(fields[2]);
            event.taskIndex = Long.parseLong(fields[3]);

            // Field 4 can be empty
            if (fields.length > 4 && !fields[4].isEmpty()) {
                event.machineId = Long.parseLong(fields[4]);
            }

            event.eventType = Integer.parseInt(fields[5]);

            if (fields.length > 6) event.user = fields[6];
            if (fields.length > 7) event.schedulingClass = Integer.parseInt(fields[7]);
            if (fields.length > 8) event.priority = Integer.parseInt(fields[8]);
            if (fields.length > 9 && !fields[9].isEmpty()) event.cpuRequest = Double.parseDouble(fields[9]);
            if (fields.length > 10 && !fields[10].isEmpty()) event.memoryRequest = Double.parseDouble(fields[10]);
            if (fields.length > 11 && !fields[11].isEmpty()) event.diskRequest = Double.parseDouble(fields[11]);
            if (fields.length > 12) event.otherField = Integer.parseInt(fields[12]);

            return event;
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

