package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.StageInfo;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import clusterdata.utils.GZIPCsvSource;
import clusterdata.utils.JobEventParser;
import clusterdata.utils.TaskEventParser;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.MapState;
import org.apache.flink.api.common.state.MapStateDescriptor;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.util.Collector;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        System.out.println("output  " + outputPath);
        final long sessionGap = params.getLong("sesssize", 600) * 1000L;  // Convert to milliseconds

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);  // Single parallelism for deterministic output

        // Read task events from gzipped CSV file
        DataStream<String> taskLines = env.addSource(
            AppBase.taskSourceOrTest(new GZIPCsvSource(taskInput))
        );

        // Parse task events - filter for SUBMIT events only
        DataStream<TaskEvent> taskSubmitEvents = taskLines
            .filter(line -> !line.isEmpty())
            .map(new MapFunction<String, TaskEvent>() {
                @Override
                public TaskEvent map(String line) throws Exception {
                    return TaskEventParser.parseTaskEvent(line);
                }
            })
            .filter(event -> event != null && event.eventType == 0);  // 0 = SUBMIT event

        // Read job events from gzipped CSV file
        DataStream<String> jobLines = env.addSource(
            AppBase.jobSourceOrTest(new GZIPCsvSource(jobInput))
        );

        // Parse job events - filter for FINISH events
        DataStream<JobEvent> jobFinishEvents = jobLines
            .filter(line -> !line.isEmpty())
            .map(new MapFunction<String, JobEvent>() {
                @Override
                public JobEvent map(String line) throws Exception {
                    return JobEventParser.parseJobEvent(line);
                }
            })
            .filter(event -> event != null && event.eventType == 4);  // 4 = FINISH event

        // Process task submit events and identify stages
        DataStream<String> result = taskSubmitEvents
            .keyBy(TaskEvent::getJobId)
            .process(new StageDetectionFunction(sessionGap));

        // Write output
        result.addSink(AppBase.sinkOrTest(
            new SinkFunction<String>() {
                @Override
                public void invoke(String value, Context context) throws Exception {
                    System.out.println(value);
                }
            }
        ));

        // Alternative: write to file
        if (outputPath != null) {
            result.writeAsText(outputPath);
        }

        env.execute("LongestSessionPerJob");
    }

    public static class StageDetectionFunction extends KeyedProcessFunction<Long, TaskEvent, String> {
        private long sessionGapMillis;
        private transient MapState<Integer, StageInfo> stages;  // stageId -> StageInfo
        private transient MapState<String, Integer> stageCounter;  // "count" -> current stage id

        public StageDetectionFunction(long sessionGapMillis) {
            this.sessionGapMillis = sessionGapMillis;
        }

        @Override
        public void open(Configuration parameters) {
            MapStateDescriptor<Integer, StageInfo> stagesDesc =
                new MapStateDescriptor<>("stages",
                    TypeInformation.of(new TypeHint<Integer>() {}),
                    TypeInformation.of(new TypeHint<StageInfo>() {}));
            stages = getRuntimeContext().getMapState(stagesDesc);

            MapStateDescriptor<String, Integer> counterDesc =
                new MapStateDescriptor<>("stageCounter",
                    TypeInformation.of(new TypeHint<String>() {}),
                    TypeInformation.of(new TypeHint<Integer>() {}));
            stageCounter = getRuntimeContext().getMapState(counterDesc);
        }

        @Override
        public void processElement(TaskEvent event, Context ctx, Collector<String> out) throws Exception {
            Long jobId = ctx.getCurrentKey();
            long eventTimeMs = event.timestamp / 1000;  // Convert microseconds to milliseconds

            // Get current stage counter
            Integer currentStageId = stageCounter.get("current");
            if (currentStageId == null) {
                currentStageId = 0;
            }

            // Get the current stage
            StageInfo currentStage = stages.get(currentStageId);

            // Determine if we need to start a new stage
            if (currentStage == null) {
                // First stage for this job
                currentStage = new StageInfo(1, eventTimeMs, eventTimeMs);
                stages.put(currentStageId, currentStage);
            } else {
                // Check if gap is > session gap (10 minutes = 600000 ms)
                long timeSinceLastSubmit = eventTimeMs - currentStage.lastSubmitTime;

                if (timeSinceLastSubmit > sessionGapMillis) {
                    // Start a new stage
                    currentStageId++;
                    currentStage = new StageInfo(1, eventTimeMs, eventTimeMs);
                    stages.put(currentStageId, currentStage);
                } else {
                    // Continue current stage
                    currentStage.taskCount++;
                    currentStage.lastSubmitTime = eventTimeMs;
                    stages.put(currentStageId, currentStage);
                }
            }

            stageCounter.put("current", currentStageId);

            // Register a timer for cleanup (when job finishes or after long inactivity)
            // Timer at current time + session gap to check for end of stage
            ctx.timerService().registerEventTimeTimer(eventTimeMs + sessionGapMillis + 1);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            Long jobId = ctx.getCurrentKey();

            // Find the longest stage for this job
            int maxTaskCount = 0;

            try {
                for (StageInfo stageInfo : stages.values()) {
                    if (stageInfo.taskCount > maxTaskCount) {
                        maxTaskCount = stageInfo.taskCount;
                    }
                }
            } catch (Exception e) {
                // Handle iteration exception
            }

            // Only emit if we have processed some stages
            if (maxTaskCount > 0) {
                String result = "(" + jobId + "," + maxTaskCount + ")";
                out.collect(result);
            }
        }
    }

}

