            MapStateDescriptor<String, Boolean> emittedDesc =
                new MapStateDescriptor<>("resultEmitted",
                    TypeInformation.of(new TypeHint<String>() {}),
                    TypeInformation.of(new TypeHint<Boolean>() {}));
            resultEmitted = getRuntimeContext().getMapState(emittedDesc);
        }

        @Override
        public void processElement(TaskEvent event, Context ctx, Collector<String> out) throws Exception {
            Long jobId = ctx.getCurrentKey();
            long eventTimeMs = event.timestamp / 1000;  // Convert microseconds to milliseconds

            // Get current stage counter
            Integer currentStageId = stageCounter.get("current");
            if (currentStageId == null) {
                currentStageId = 0;
            }

            // Get the current stage
            StageInfo currentStage = stages.get(currentStageId);
            Long lastTime = lastEventTime.get("lastEventTime");

            // Determine if we need to start a new stage
            if (currentStage == null) {
                // First stage for this job
                currentStage = new StageInfo(1, eventTimeMs, eventTimeMs);
                stages.put(currentStageId, currentStage);
            } else {
                // Check if gap is > session gap (10 minutes = 600000 ms)
                long timeSinceLastSubmit = lastTime != null ? eventTimeMs - lastTime : 0;

                if (lastTime != null && timeSinceLastSubmit > sessionGapMillis) {
                    // Start a new stage
                    currentStageId++;
                    currentStage = new StageInfo(1, eventTimeMs, eventTimeMs);
                    stages.put(currentStageId, currentStage);
                } else {
                    // Continue current stage
                    currentStage.taskCount++;
                    currentStage.lastSubmitTime = eventTimeMs;
                    stages.put(currentStageId, currentStage);
                }
            }

            stageCounter.put("current", currentStageId);
            lastEventTime.put("lastEventTime", eventTimeMs);

            // Register a timer to detect inactivity and emit results if needed
            long timerTime = eventTimeMs + sessionGapMillis + 1;
            ctx.timerService().registerEventTimeTimer(timerTime);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            Long jobId = ctx.getCurrentKey();
            Long lastTime = lastEventTime.get("lastEventTime");
            Boolean emitted = resultEmitted.get("resultEmitted");

            // Only emit if we haven't already and the timeout is valid
            if ((emitted == null || !emitted) && lastTime != null) {
                long timeSinceLastEvent = timestamp - lastTime;
                if (timeSinceLastEvent >= sessionGapMillis) {
                    // Time to emit the result
                    int maxTaskCount = 0;
                    try {
                        for (StageInfo stageInfo : stages.values()) {
                            if (stageInfo.taskCount > maxTaskCount) {
                                maxTaskCount = stageInfo.taskCount;
                            }
                        }
                    } catch (Exception e) {
                        // Handle iteration exception
                    }

                    if (maxTaskCount > 0) {
                        String result = "(" + jobId + "," + maxTaskCount + ")";
                        out.collect(result);
                        resultEmitted.put("resultEmitted", true);
                    }
                }
            }
        }
    }

}
